unsigned cases=0;void need(bool q,const char*why){if(!q){std::fprintf(stderr,"FAIL %s\n",why);std::exit(1);}}
template<class F>void test(const char*n,F f){f();++cases;std::printf("CASE_PASS %s\n",n);}
struct Events{std::vector<std::string> ev,why;void operator()(const char*e,r::Cause,const char*w){ev.emplace_back(e);why.emplace_back(w);}unsigned count(const char*n)const{return unsigned(std::count(ev.begin(),ev.end(),n));}};
r::Actor actor(unsigned id=1){r::Actor a;a.id=id;a.gen=1;a.variant=V::Red;std::memcpy(a.stage,"F_SP121",8);a.room=3;a.layer=6;a.health=330;a.ready=true;a.perceived=true;a.mode=r::Find;a.state=4;a.pos={0,0,0};a.home=a.pos;a.range=5000;a.end=40;return a;}
r::Link link(){r::Link l;l.id=10;l.present=l.basic=l.canary=l.safe=l.los=true;std::memcpy(l.stage,"F_SP121",8);l.room=3;l.layer=6;l.pos={300,0,0};l.motion=r::Motion::Quiet;l.proc=3;l.timer=0;return l;}
struct Lab{std::array<r::State,64> states{};r::Actor a=actor();r::Link l=link();Events ev;r::State& s(){return states[0];}Lab(){r::state_for(states,0,a,7);}void pre(){r::pre(s(),a,l,ev);r::before_blow(s(),a);}r::Rate post(){return r::post(s(),a,ev);}r::Rate start(int clip=5){a.mode=r::Attack;a.state=0;a.b=a.c=false;a.frame=0;a.rate=1;pre();a.state=clip==5?1:2;a.b=clip==5;a.c=clip==6;a.frame=1;return post();}void end(){a.mode=r::Find;a.state=0;a.b=a.c=false;a.frame=0;a.rate=1;post();a.state=4;} };
// Exact source-shaped native excerpt port: action clears attack bits, executeAttack reads current frame then play advances; cc_set uses updated model.
// This is not engine collision/animation/audio. Contact/guard/wall controls below are explicit inputs, not proof of physical game contacts.
struct NativeTrace{unsigned voice10=0,sound125=0,sound19=0,voice7=0,sound115=0,repairs=0,active=0;float push=0,max_delta=0;std::vector<float> active_pre,model_frames;};
constexpr float tb[]={0,0,0,0,15.3f,38.4f,63.3f,86.2f,103.3f,112};constexpr float tc[]={0,31.3f,72.7f,91.5f,91.5f,91.5f,91.5f,91.5f,91.5f,91.5f};
NativeTrace trace(int clip,float speed,bool repair){NativeTrace t;float old=0;for(float f=1;f<35;f+=speed){
 bool skipped=false;if(clip==5){if(r::pass(f,speed,40,10)){++t.voice10;skipped=r::pass(f,speed,40,12.5f);}else if(r::pass(f,speed,40,12.5f))++t.sound125;else if(r::pass(f,speed,40,19))++t.sound19;}
 else{if(r::pass(f,speed,40,7))++t.voice7;else if(r::pass(f,speed,40,11.5f))++t.sound115;}
 if(f>=14&&f<=22){++t.active;t.active_pre.push_back(f);t.model_frames.push_back(f+speed);}int i=int(f-9);float next=i>=0?(clip==5?tb[std::min(i,9)]:tc[std::min(i,9)]):0;const float delta=next-old;t.push+=delta;t.max_delta=std::max(t.max_delta,delta);old=next;
 if(repair&&skipped){++t.sound125;++t.repairs;}
 }return t;}
